'use strict';
function templateSVG(p){const objects=[...p.traps,...p.slots,...p.structures,...p.blocks],isoPoint=(x,y)=>({x:(x-y)*.8,y:(x+y)*.46}),corners=objects.flatMap(b=>[[b.x,b.y],[b.x+b.w,b.y],[b.x,b.y+b.h],[b.x+b.w,b.y+b.h]].map(([x,y])=>isoPoint(x,y))),minX=Math.min(...corners.map(p=>p.x))-2,minY=Math.min(...corners.map(p=>p.y))-2,w=Math.max(...corners.map(p=>p.x))-minX+2,h=Math.max(...corners.map(p=>p.y))-minY+2,poly=b=>[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]].map(([x,y])=>{const p=isoPoint(x,y);return p.x+','+p.y}).join(' '),draw=(b,color)=>`<polygon points="${poly(b)}" fill="${color}" stroke="#f6f7f2" stroke-width=".1"/>`;return`<svg viewBox="${minX} ${minY} ${w} ${h}" class="template-preview" role="img" aria-label="${esc(p.name)} layout preview">${p.blocks.map(b=>draw(b,'#bd8d7d')).join('')}${p.slots.map(b=>draw(b,b.trap===2?'#b4bfa8':'#8ca78a')).join('')}${p.structures.map(b=>draw(b,b.kind==='hq'?'#b49651':b.kind==='node'?'#577c59':'#87927b')).join('')}${p.traps.map(t=>{const c=isoPoint(t.x+1.5,t.y+1.5);return draw(t,'#315840')+`<text x="${c.x}" y="${c.y+.2}" text-anchor="middle" font-size=".8" fill="white">BT${t.id}</text>`}).join('')}</svg>`}
function openTemplateLibrary(){openModal(`<div class="eyebrow">TEMPLATES</div><h2>Choose a layout</h2><p>Empty city spaces, ready for your roster.</p><div class="template-catalogue">${Hive.templateCatalogue().map(p=>`<button class="template-card" data-template="${p.id}" ${p.id==='lun'?'id="chooseLun"':''}>${templateSVG(p)}<strong>${esc(p.name)}</strong><span>${p.slots.length} city spaces · ${p.traps.length} ${p.traps.length===1?'trap':'traps'}</span><small>${esc(p.description)}</small></button>`).join('')}</div>`);$$('[data-template]').forEach(b=>b.onclick=()=>openTemplatePreview(b.dataset.template))}
function openTemplatePreview(id){const p=Hive.templateGeometry(id);openModal(`<div class="eyebrow">TEMPLATE PREVIEW</div><h2>${esc(p.name)}</h2>${templateSVG(p)}<p>${p.slots.length} city spaces · ${p.traps.length} ${p.traps.length===1?'trap':'traps'} · ${p.structures.filter(b=>b.kind==='flag').length} banners${p.structures.some(b=>b.kind==='hq')?' · HQ':''}${p.structures.some(b=>b.kind==='node')?' · Node':''}</p><p>${esc(p.origin)}${p.source?` · <a href="${esc(p.source)}" target="_blank" rel="noopener">Source</a>`:''}</p><div class="two"><label>BT1 X<input id="templateX" type="number" min="0" max="1197" value="${state.settings.anchorX}" inputmode="numeric"></label><label>BT1 Y<input id="templateY" type="number" min="0" max="1197" value="${state.settings.anchorY}" inputmode="numeric"></label></div><p id="templateFit" class="notice"></p><p>Replaces this map and unassigns all cities, including locked ones. Roster groups, attendance and the other map stay saved. Undo is available.</p><div class="actions"><button class="primary" id="${id==='lun'?'applyLunLayout':'applyTemplate'}" data-apply-template="${id}">Use ${esc(p.name)}</button><button id="backTemplates">Back to templates</button><button id="cancelLunLayout">Cancel</button></div>`);const button=$('[data-apply-template]');let result;const update=()=>{try{if(!$('#templateX').value||!$('#templateY').value)throw Error('Enter BT1 coordinates.');result=Hive.applyHiveTemplate(state,id,{x:+$('#templateX').value,y:+$('#templateY').value});$('#templateFit').textContent=(result.state.mapMode==='terrain'?`Blocked city spaces: ${result.blocked}. Trap / structure conflicts: ${result.fixedConflicts}. `:'')+'Geometry only. Check territory coverage in game.';button.disabled=false}catch(e){result=null;button.disabled=true;$('#templateFit').textContent=e.message}};$('#templateX').oninput=update;$('#templateY').oninput=update;update();button.onclick=()=>{if(!result)return;commit(()=>state=result.state);closeModal();selectedMember=null;selectedSlot=null;activeTrap='all';setTool('select');render();fit();toast(p.name+' loaded. Assign players from Member queue. Undo is available.')};$('#backTemplates').onclick=openTemplateLibrary;$('#cancelLunLayout').onclick=closeModal}
$('#loadLunBtn').textContent='Templates';$('#loadLunBtn').onclick=openTemplateLibrary;function openLunTemplate(){openTemplatePreview('lun')}
const requestedTemplate=new URLSearchParams(location.search).get('layout');if(requestedTemplate&&Hive.templateCatalogue().some(p=>p.id===requestedTemplate)&&!readonly)setTimeout(()=>openTemplatePreview(requestedTemplate),0);
